export function journeyState(p){p.journey||={counts:{},claimed:[]};p.journey.counts||={};p.journey.claimed||=[];return p.journey;}
export function journeyEvent(p,type,event={}){if(event.training)return;const s=journeyState(p);if(type==='kill'){s.counts.kills=(s.counts.kills||0)+1;if(event.division==='WORLD')s.counts.world=(s.counts.world||0)+1;if(event.division==='CATACLYSM')s.counts.cataclysm=(s.counts.cataclysm||0)+1;}else if(type==='strike'){s.counts.strikes=(s.counts.strikes||0)+1;if(event.skill)s.counts.skills=(s.counts.skills||0)+1;if(event.critical)s.counts.criticals=(s.counts.criticals||0)+1;}else if(type==='dungeon')s.counts.dungeons=(s.counts.dungeons||0)+1;}
export function orderStatus(p,id){const d=ORDERS.find(x=>x.id===id);if(!d)return null;const s=journeyState(p),index=ORDERS.indexOf(d),claimed=s.claimed.includes(id),locked=p.level<d.level||(index>0&&!s.claimed.includes(ORDERS[index-1].id)),goals=d.goals.map(([key,target,text])=>({key,target,text,count:Math.min(target,key==='legacy'?Object.keys(p.legacy?.clears||{}).filter(k=>[1,2,3].includes(Number(k))).length:s.counts[key]||0)}));return{d,claimed,locked,goals,ready:!claimed&&!locked&&goals.every(g=>g.count>=g.target)};}
export function claimOrder(p,id){const st=orderStatus(p,id);if(!st||!st.ready)return{ok:false,reason:st?.claimed?'Recompensa já recebida.':'Conclua os objetivos e a ordem anterior.'};const s=journeyState(p);s.claimed.push(id);p.gold=(p.gold||0)+st.d.gold;p.materials||={};for(const [k,v] of Object.entries(st.d.reward))p.materials[k]=(p.materials[k]||0)+v;p.journeyTitles||=[];if(!p.journeyTitles.includes(st.d.title))p.journeyTitles.push(st.d.title);p.activeTitle=st.d.title;return{ok:true,title:st.d.title};}
